    /** IN-۱۲۳۴ — پیشوند نام آموزشگاه، بدون سال چون شماره باید یکتا بماند. */
    public static function nextNumber(): string
    {
        $next = (int) (static::query()->max('id') ?? 0) + 1;

        return 'IN-'.str_pad((string) $next, 6, '0', STR_PAD_LEFT);
    }

